// Twilio signs every webhook: X-Twilio-Signature = Base64(HMAC-SHA1(Auth Token, the webhook URL + every POST
// field name and value, sorted by name)). Plain JavaScript: the n8n server needs no special settings.
// The check is ON once your Twilio Auth Token is in the Settings node. While that field is empty, messages are
// accepted (the webhook path is long and hard to guess), so fill it in when you can.
// Plain-JavaScript HMAC-SHA1 (no require, no Buffer): works in any n8n Code node without server settings.
function utf8(s) {
  const t = unescape(encodeURIComponent(String(s)));
  const out = new Array(t.length);
  for (let i = 0; i < t.length; i++) out[i] = t.charCodeAt(i);
  return out;
}
