const S = $('Settings').first().json;
const req = $('Twilio WhatsApp message in').first().json;
const headers = req.headers || {};
const params = req.body || {};
const token = String(S.twilio_auth_token || '').trim();
const signature = String(headers['x-twilio-signature'] || '');
if (!token) {
  return [{ json: { valid: true, checked: false, reason: 'Signature check off: paste your Twilio Auth Token into Settings to switch it on' } }];
}

// The exact URL Twilio called: the Settings value if given, else n8n's own idea of it, else rebuilt from the proxy headers.
const urls = new Set();
const add = (u) => { if (u) urls.add(String(u).trim()); };
add(S.webhook_public_url);
add(req.webhookUrl);
const host = String(headers['x-forwarded-host'] || headers.host || '').split(',')[0].trim();
const proto = String(headers['x-forwarded-proto'] || 'https').split(',')[0].trim();
if (host) add(`${proto}://${host}/webhook/shubhlabh-whatsapp-twilio`);
try {
  const query = req.query && Object.keys(req.query).length ? new URLSearchParams(req.query).toString() : '';
  if (query) for (const u of [...urls]) if (!u.includes('?')) urls.add(u + '?' + query);
} catch (e) { /* no query string support: keep the plain URLs */ }
for (const u of [...urls]) {  // Twilio may sign with or without the default port
  const m = u.match(/^(https?):\/\/([^/:?#]+)(:\d+)?(.*)$/i);
  if (!m) continue;
  urls.add(m[3] ? `${m[1]}://${m[2]}${m[4]}` : `${m[1]}://${m[2]}${m[1].toLowerCase() === 'https' ? ':443' : ':80'}${m[4]}`);
}

const names = Object.keys(params).sort();
const payload = (url) => url + names.map((k) => [].concat(params[k]).map((v) => k + String(v ?? '')).join('')).join('');
let valid = false;
let reason = '';
if (!signature) reason = 'No X-Twilio-Signature header: not a Twilio request';
else {
  valid = [...urls].some((u) => base64(hmacSha1(token, payload(u))) === signature);
  if (!valid) reason = 'Signature mismatch: check the Twilio Auth Token in Settings, or paste the exact URL Twilio calls into webhook_public_url';
}
return [{ json: { valid, checked: true, reason } }];

