const msg = $('Twilio WhatsApp message in').first().json.body || {};
const text = String(msg.Body || '').trim().slice(0, 1000);
const numMedia = parseInt(msg.NumMedia || '0', 10) || 0;
const mediaType = String(msg.MediaContentType0 || '').toLowerCase();
const from = String(msg.From || '');  // e.g. whatsapp:+919876543210

const SEP = String.raw`\s*(?:is|hai|=|:|-|at|pe|par|of|ka|ki)?\s*`;
const NUM = String.raw`(?:₹|rs\.?|inr)?\s*(\d+(?:\.\d+)?)(?![\d.]|\s*%)`;
const STOP = /^\s*(stop|unsubscribe|band karo|बंद)\s*$/i;
const STATUS = /^\s*(?:status|plan\s+status|status\s+(?:of\s+)?(?:my\s+)?plan|my\s+plan|mera\s+plan|plan\s+kaha+n?\s+hai|where\s+is\s+my\s+plan)\s*[?.!]*\s*$/i;
const PLAN = /\b(plan|campaign|designer|full plan|poora plan)\b/i;
const PRICE = new RegExp(String.raw`\b(?:selling\s+price|sell\w*|sp|offer\s+price|offer|price|bech\w*|daam|bhav|rate|now)` + SEP + NUM, 'i');
const MRP = new RegExp(String.raw`\bm\.?\s?r\.?\s?p\.?` + SEP + NUM, 'i');
const MY_PRICE = new RegExp(String.raw`\b(?:my|mera|meri|apna|hamara|our)\s*(?:price|daam|bhav|rate)?` + SEP + NUM, 'i');
const PCT = /(\d+(?:\.\d+)?)\s*%/;
const offerLike = PRICE.test(text) || MY_PRICE.test(text) || (MRP.test(text) && PCT.test(text));

let lane = 'text';
if (STOP.test(text)) lane = 'stop';
else if (numMedia > 0 && msg.MediaUrl0 && (mediaType.startsWith('image/') || mediaType === 'application/pdf')) lane = 'photo';
else if (PLAN.test(text) && !STATUS.test(text) && !offerLike) lane = 'plan';

const S = $('Settings').first().json;
const salt = String(S.relay_token || S.twilio_auth_token || 'shubhlabh');
return [{ json: {
  lane,
  from,
  to: from.replace(/^whatsapp:/i, ''),            // the Twilio node adds "whatsapp:" itself
  body: text,
  numMedia: String(numMedia),
  mediaUrl: String(msg.MediaUrl0 || ''),
  mediaType,
  twilioNumber: String(msg.To || '').replace(/^whatsapp:/i, ''),
  senderRef: hex(hmacSha1(salt, from)).slice(0, 12),  // for logs: never the number
  receivedAt: new Date().toISOString(),
} }];

// Bounded loop: at most 16 checks (15 s wait + up to 5 s long-poll each), about 5 minutes.
const MAX_CHECKS = 16;
const attempt = $runIndex + 1;
return [{ json: { attempt, give_up: attempt >= MAX_CHECKS } }];

// Runs when any execution of this workflow fails (n8n uses a workflow's own Error Trigger
// when no other error workflow is set). Owner-facing only: the sender already got an apology
// from the apology lane wherever ShubhLabh could not answer.
const e = $input.first().json;
return [{ json: {
  time: new Date().toISOString(),
  workflow: (e.workflow && e.workflow.name) || '',
  node: (e.execution && e.execution.lastNodeExecuted) || '',
  message: String((e.execution && e.execution.error && e.execution.error.message) || (e.trigger && e.trigger.error && e.trigger.error.message) || 'unknown error').slice(0, 300),
  execution_url: (e.execution && e.execution.url) || '',
} }];
